/**
 * The contract `menu.tsx` (native, on the popover) and `menu.web.tsx` (radix `DropdownMenu`)
 * both implement. Its own module for the usual reason: Metro resolves `./menu` to `menu.web.tsx`
 * on web, so the web file cannot import shared types from `./menu` without importing itself.
 *
 * A menu is a popover of actions. It exists because the popover alone left each app to build the
 * rows by hand — a `Pressable role="menuitem"` with no `role="menu"` around it, no arrow keys, no
 * focus back on the trigger, and an `onSelect` that had to close the popover itself because the
 * caller owned `open`. Here the rows are `MenuItem`, the menu closes when one is chosen, and the
 * caller owns nothing unless it wants to.
 */
import type { ReactElement, ReactNode } from "react";

export type MenuProps = {
  /** Both optional, together, as on `Popover`: pass neither and the menu keeps its own state. */
  open?: boolean | undefined;
  onOpenChange?: ((open: boolean) => void) | undefined;
  defaultOpen?: boolean | undefined;
  children: ReactNode;
};

export type MenuTriggerProps = {
  /**
   * Hand the press handler to the single child element rather than wrapping it. Always pass it
   * around a `Button`: a `Pressable` wrapping a `Button` never fires on native.
   */
  asChild?: boolean | undefined;
  children: ReactNode;
};

export type MenuContentProps = {
  className?: string | undefined;
  /** Web only — the native sheet is centred and has nothing to align to. */
  align?: "start" | "center" | "end" | undefined;
  /**
   * The menu's name. On web radix names it after its trigger already; on native there is no
   * `aria-labelledby` to point at the trigger, so a trigger with no text (a ⋯ button) wants this.
   */
  "aria-label"?: string | undefined;
  children?: ReactNode;
};

export type MenuItemProps = {
  /** An icon from `@cubeui/icons`. It takes the row's colour — `text-destructive` on a destructive row. */
  icon?: ReactNode;
  /** The row's text, and what typeahead matches on the web. */
  label: string;
  /** After the label, at the far edge: a shortcut, a count, a check. A string is drawn muted. */
  trailing?: ReactNode;
  /** Draw the row in the destructive colour, for the action that deletes. */
  destructive?: boolean | undefined;
  disabled?: boolean | undefined;
  /** Runs when the row is chosen. The menu closes itself afterwards; do not close it here. */
  onSelect?: (() => void) | undefined;
  /**
   * The row hands focus to something else — a field it reveals with `autoFocus` — so this close
   * must not put focus back on the trigger, which would blur that target (and close it on `onBlur`
   * before anything is typed). Only for the close this row
   * causes: Escape, a click outside and every other row still return focus to the trigger.
   */
  focusesElsewhere?: boolean | undefined;
  className?: string | undefined;
  /**
   * Where the row goes, with no router: on the web the row is an `<a href>`, so it navigates,
   * opens in a new tab and shows its URL. On device it does nothing more than `onSelect` — a
   * native app navigates through its router, which is `link`.
   */
  href?: string | undefined;
  /**
   * The app's router link, as an element with no children — `<Link to="/x" preload="intent" />`.
   * The row is drawn inside it, so on the web the menu item *is* the router's `<a>`, and hover and
   * focus reach the link's own handlers (which is what lets a router preload on intent). On
   * device it is cloned with `asChild` around the row, the `<Link asChild>` convention. Wins over
   * `href`; a `disabled` row renders neither and does not navigate.
   */
  link?: ReactElement | undefined;
};

export type MenuSeparatorProps = {
  className?: string | undefined;
};

export const MENU_CONTENT_CLASS = "min-w-[8rem] p-1";
export const MENU_ITEM_CLASS = "w-full flex-row items-center gap-2 rounded-sm px-2 py-1.5";
export const MENU_ITEM_TEXT_CLASS = "flex-1 text-sm";
export const MENU_TRAILING_CLASS = "ml-auto text-xs text-muted-foreground";
export const MENU_SEPARATOR_CLASS = "-mx-1 my-1 h-px bg-border";

/**
 * The toggle rows take `MenuItem`'s row — `icon`, `label`, `trailing`, `disabled` — and not its
 * `destructive` or `onSelect`: a row that is on or off is a setting, not an action, and what it
 * reports is its new state.
 */
type MenuToggleRowProps = Omit<MenuItemProps, "destructive" | "onSelect">;

export type MenuCheckboxItemProps = MenuToggleRowProps & {
  checked: boolean;
  /**
   * Runs with the row's new state. The menu stays open, so a list of these is toggled one row
   * after another without reopening it.
   */
  onCheckedChange?: ((checked: boolean) => void) | undefined;
};

export type MenuRadioGroupProps = {
  /** The `value` of the row that is on. */
  value: string;
  /** Runs with the chosen row's `value`. The menu closes afterwards, as radix's does. */
  onValueChange?: ((value: string) => void) | undefined;
  /** What the group chooses — worth passing when the menu holds more than one group. */
  "aria-label"?: string | undefined;
  children?: ReactNode;
};

export type MenuRadioItemProps = MenuToggleRowProps & {
  /** Handed to the group's `onValueChange` when the row is chosen. */
  value: string;
};

/**
 * What a web row adds to `MENU_ITEM_CLASS`: radix's disabled state and the icon sizing that
 * `IconClassContext` does on native. Shared so the toggle rows are `MenuItem`'s row, not a copy.
 */
export const MENU_ITEM_WEB_CLASS =
  "relative flex cursor-default select-none outline-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0";
/**
 * The slot the ✓ sits in, at the row's far edge. It is kept when the row is off, so a column of
 * labels and trailing nodes lines up whichever rows are on.
 */
export const MENU_INDICATOR_CLASS = "size-4 shrink-0 items-center justify-center";

/**
 * The native menu: the popover's centred sheet with a `role="menu"` inside it and a
 * `role="menuitem"` per row. `menu.web.tsx` is the counterpart and `menu-base.ts` the contract.
 *
 * Built on `Popover` rather than beside it, so the sheet, its backdrop and the back button are
 * the popover's and are not written twice. The menu keeps the open state itself and hands it to
 * the popover controlled, because a row has to close the sheet it sits in and the popover's own
 * context is not exported.
 *
 * What radix does on the web and this does not: arrow keys and typeahead. A touch screen has
 * neither, and the screen reader walks the rows by swipe. Focus does go back to the trigger when
 * the sheet shuts — by `focus()` under react-native-web, and on device as an accessibility focus
 * event, which is the only focus a `View` has there — unless the row chosen was
 * `focusesElsewhere`, whose target keeps it.
 */

import {
  cloneElement,
  createContext,
  isValidElement,
  type ReactElement,
  type Ref,
  type RefObject,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";
import { AccessibilityInfo, Platform, Pressable, type Role, Text, View } from "react-native";
import { Check } from "@/components/ui/icons";
import { IconClassContext } from "@/components/ui/icons-base";
import {
  MENU_CONTENT_CLASS,
  MENU_INDICATOR_CLASS,
  MENU_ITEM_CLASS,
  MENU_ITEM_TEXT_CLASS,
  MENU_SEPARATOR_CLASS,
  MENU_TRAILING_CLASS,
  type MenuCheckboxItemProps,
  type MenuContentProps,
  type MenuItemProps,
  type MenuProps,
  type MenuRadioGroupProps,
  type MenuRadioItemProps,
  type MenuSeparatorProps,
  type MenuTriggerProps,
} from "@/components/ui/menu-base";
import { Popover, PopoverContent } from "@/components/ui/popover";
import { cn } from "@/lib/utils";

type MenuState = {
  open: boolean;
  setOpen: (open: boolean) => void;
  triggerRef: RefObject<View | null>;
  /** Set by a `focusesElsewhere` row, read and cleared on the close edge. */
  skipReturnRef: RefObject<boolean>;
};

const MenuContext = createContext<MenuState>({
  open: false,
  setOpen: () => {},
  triggerRef: { current: null },
  skipReturnRef: { current: false },
});

/** Put focus back on the trigger, in whichever sense of focus the platform has. */
function returnFocus(node: View | null) {
  if (!node) return;
  if (Platform.OS === "web") {
    (node as unknown as { focus?: () => void }).focus?.();
  } else {
    AccessibilityInfo.sendAccessibilityEvent(node, "focus");
  }
}

function Menu({ open, onOpenChange, defaultOpen = false, children }: MenuProps) {
  // Uncontrolled state kept unconditionally and read only when the caller passed no `open`, the
  // same arrangement as `popover.tsx`.
  const [uncontrolled, setUncontrolled] = useState(defaultOpen);
  const isOpen = open ?? uncontrolled;
  const setOpen = (next: boolean) => {
    if (open === undefined) setUncontrolled(next);
    onOpenChange?.(next);
  };

  const triggerRef = useRef<View | null>(null);
  const skipReturnRef = useRef(false);
  const wasOpen = useRef(isOpen);
  useEffect(() => {
    // On the close edge only, however it closed: a row, the backdrop or the back button. A
    // `focusesElsewhere` row has already moved focus to where it belongs, so leave it there.
    if (wasOpen.current && !isOpen) {
      if (!skipReturnRef.current) returnFocus(triggerRef.current);
      skipReturnRef.current = false;
    }
    wasOpen.current = isOpen;
  }, [isOpen]);

  return (
    <MenuContext.Provider value={{ open: isOpen, setOpen, triggerRef, skipReturnRef }}>
      <Popover open={isOpen} onOpenChange={setOpen}>
        {children}
      </Popover>
    </MenuContext.Provider>
  );
}

function MenuTrigger({ asChild, children }: MenuTriggerProps) {
  const { open, setOpen, triggerRef } = useContext(MenuContext);
  if (asChild && isValidElement(children)) {
    // The child's own ref still gets the node; the menu only needs to read it too.
    const own = (children.props as { ref?: Ref<View> }).ref;
    return cloneElement(
      children as ReactElement<{
        onPress?: () => void;
        ref?: Ref<View>;
        "aria-expanded"?: boolean;
      }>,
      {
        onPress: () => setOpen(true),
        "aria-expanded": open,
        ref: (node: View | null) => {
          triggerRef.current = node;
          if (typeof own === "function") own(node);
          else if (own) own.current = node;
        },
      },
    );
  }
  return (
    // The `role` is hand-written because a `<button>` has no native counterpart.
    <Pressable role="button" aria-expanded={open} ref={triggerRef} onPress={() => setOpen(true)}>
      {children}
    </Pressable>
  );
}

function MenuContent({ className, "aria-label": ariaLabel, children }: MenuContentProps) {
  return (
    <PopoverContent className={cn(MENU_CONTENT_CLASS, "w-64", className)}>
      <View role="menu" aria-label={ariaLabel}>
        {children}
      </View>
    </PopoverContent>
  );
}

function MenuItem({
  icon,
  label,
  trailing,
  destructive = false,
  disabled = false,
  onSelect,
  focusesElsewhere = false,
  className,
  link,
}: MenuItemProps) {
  const { setOpen, skipReturnRef } = useContext(MenuContext);
  const ink = destructive ? "text-destructive" : "text-popover-foreground";
  const row = (
    <Pressable
      role="menuitem"
      disabled={disabled}
      aria-disabled={disabled}
      onPress={() => {
        skipReturnRef.current = focusesElsewhere;
        onSelect?.();
        setOpen(false);
      }}
      className={cn(
        MENU_ITEM_CLASS,
        destructive ? "active:bg-destructive/10" : "active:bg-accent",
        disabled && "opacity-50",
        className,
      )}
    >
      {/* Colour does not inherit on native, so the row's ink reaches the icon through the
          context and the label through its own class. */}
      <IconClassContext.Provider value={cn("size-4 shrink-0", ink)}>
        {icon}
        <Text numberOfLines={1} className={cn(MENU_ITEM_TEXT_CLASS, ink)}>
          {label}
        </Text>
        {typeof trailing === "string" ? (
          <Text className={MENU_TRAILING_CLASS}>{trailing}</Text>
        ) : (
          trailing
        )}
      </IconClassContext.Provider>
    </Pressable>
  );
  // `href` alone is only the web's: there is no URL to open on device, and the app's router is
  // what navigates. Its link takes the row the way it takes a `Button` — `asChild`, which hands
  // the row its press handler beside the row's own `onSelect`. A disabled row is not handed over.
  return link && !disabled
    ? cloneElement(link as ReactElement<{ asChild?: boolean }>, { asChild: true }, row)
    : row;
}

function MenuSeparator({ className }: MenuSeparatorProps) {
  return <View role="separator" className={cn(MENU_SEPARATOR_CLASS, className)} />;
}

type ToggleRowProps = Pick<
  MenuCheckboxItemProps,
  "icon" | "label" | "trailing" | "disabled" | "className"
> & {
  kind: "checkbox" | "radio";
  checked: boolean;
  onPress: () => void;
};

/**
 * The row's role. ARIA's is `menuitemcheckbox` / `menuitemradio`, and react-native-web hands the
 * string to the DOM, so that is what an Expo web app gets. React Native's `Role` has neither:
 * on device an unknown role is dropped, and the row would lose the one word that makes
 * `aria-checked` read as "checked", so there it is the plain `checkbox` / `radio`.
 */
function toggleRole(kind: ToggleRowProps["kind"]): Role {
  if (Platform.OS !== "web") return kind;
  return (kind === "checkbox" ? "menuitemcheckbox" : "menuitemradio") as Role;
}

/**
 * `MenuItem`'s row with a ✓ slot at the far edge, and `aria-checked` for the state. What it does
 * when pressed — toggle and stay open, or choose and close — is the caller's.
 */
function ToggleRow({
  kind,
  checked,
  onPress,
  icon,
  label,
  trailing,
  disabled = false,
  className,
}: ToggleRowProps) {
  const ink = "text-popover-foreground";
  return (
    <Pressable
      role={toggleRole(kind)}
      aria-checked={checked}
      disabled={disabled}
      aria-disabled={disabled}
      onPress={onPress}
      className={cn(MENU_ITEM_CLASS, "active:bg-accent", disabled && "opacity-50", className)}
    >
      <IconClassContext.Provider value={cn("size-4 shrink-0", ink)}>
        {icon}
        <Text numberOfLines={1} className={cn(MENU_ITEM_TEXT_CLASS, ink)}>
          {label}
        </Text>
        {typeof trailing === "string" ? (
          <Text className={MENU_TRAILING_CLASS}>{trailing}</Text>
        ) : (
          trailing
        )}
        <View className={MENU_INDICATOR_CLASS}>{checked ? <Check /> : null}</View>
      </IconClassContext.Provider>
    </Pressable>
  );
}

/** Pressed, it reports its new state and leaves the menu open, so a list is toggled in one go. */
function MenuCheckboxItem({ checked, onCheckedChange, ...row }: MenuCheckboxItemProps) {
  return (
    <ToggleRow
      {...row}
      kind="checkbox"
      checked={checked}
      onPress={() => onCheckedChange?.(!checked)}
    />
  );
}

type RadioGroupState = Pick<MenuRadioGroupProps, "value" | "onValueChange">;

const RadioGroupContext = createContext<RadioGroupState | null>(null);

function MenuRadioGroup({
  value,
  onValueChange,
  "aria-label": ariaLabel,
  children,
}: MenuRadioGroupProps) {
  return (
    <RadioGroupContext.Provider value={{ value, onValueChange }}>
      <View role="group" aria-label={ariaLabel}>
        {children}
      </View>
    </RadioGroupContext.Provider>
  );
}

/** Chosen, it closes the menu, as the web half's radix item does: a one-of-N choice is made once. */
function MenuRadioItem({ value, ...row }: MenuRadioItemProps) {
  const group = useContext(RadioGroupContext);
  const { setOpen } = useContext(MenuContext);
  return (
    <ToggleRow
      {...row}
      kind="radio"
      checked={group?.value === value}
      onPress={() => {
        group?.onValueChange?.(value);
        setOpen(false);
      }}
    />
  );
}

export {
  Menu,
  MenuCheckboxItem,
  MenuContent,
  MenuItem,
  MenuRadioGroup,
  MenuRadioItem,
  MenuSeparator,
  MenuTrigger,
};

/**
 * The web menu: radix `DropdownMenu`, anchored to its trigger. `menu.tsx` is the native
 * counterpart and `menu-base.ts` holds the contract they share.
 *
 * Radix is the reason this half is hand-written rather than compiled: `role="menu"` with the
 * trigger as its name, arrow keys and Home/End between the rows (skipping disabled ones),
 * typeahead on each row's label, focus moved into the menu on open and back to the trigger on
 * close (unless the row chosen is `focusesElsewhere`), and the menu closing when a row is
 * chosen. None of that is layout, so none of it could come out of the React Native source.
 *
 * Each part also takes the props of the radix part it renders — `side`, `sideOffset`, `modal`,
 * `onCloseAutoFocus` — on top of the contract. Those extras are web only.
 */

import { DropdownMenu as MenuPrimitive } from "radix-ui";
import type * as React from "react";
import { cloneElement, createContext, type RefObject, useContext, useRef, useState } from "react";
import { flushSync } from "react-dom";
import { Check } from "@/components/ui/icons";
import {
  MENU_CONTENT_CLASS,
  MENU_INDICATOR_CLASS,
  MENU_ITEM_CLASS,
  MENU_ITEM_TEXT_CLASS,
  MENU_ITEM_WEB_CLASS,
  MENU_SEPARATOR_CLASS,
  MENU_TRAILING_CLASS,
  type MenuCheckboxItemProps,
  type MenuContentProps,
  type MenuItemProps,
  type MenuProps,
  type MenuRadioGroupProps,
  type MenuRadioItemProps,
  type MenuSeparatorProps,
  type MenuTriggerProps,
} from "@/components/ui/menu-base";
import { cn } from "@/lib/utils";

/** The shared contract, widened to what the radix part underneath accepts. */
type Wide<Base, Radix> = Base & Omit<Radix, keyof Base>;

type MenuState = {
  setOpen: (open: boolean) => void;
  /**
   * Whether the close in progress was caused by a `focusesElsewhere` row. A ref rather than state:
   * it is written when the row is chosen and read in `onCloseAutoFocus` after the close animation,
   * and nothing renders from it.
   */
  skipReturnRef: RefObject<boolean>;
};

const MenuContext = createContext<MenuState>({
  setOpen: () => {},
  skipReturnRef: { current: false },
});

function Menu({
  open,
  onOpenChange,
  defaultOpen = false,
  ...props
}: Wide<MenuProps, React.ComponentProps<typeof MenuPrimitive.Root>>) {
  // The menu holds the open state rather than leaving it to radix, the same arrangement as
  // `menu.tsx`, because a `focusesElsewhere` row has to close the menu itself before its action
  // runs — see `MenuItem`.
  const [uncontrolled, setUncontrolled] = useState(defaultOpen);
  const isOpen = open ?? uncontrolled;
  const setOpen = (next: boolean) => {
    if (open === undefined) setUncontrolled(next);
    onOpenChange?.(next);
  };
  const skipReturnRef = useRef(false);
  return (
    <MenuContext.Provider value={{ setOpen, skipReturnRef }}>
      <MenuPrimitive.Root data-slot="menu" {...props} open={isOpen} onOpenChange={setOpen} />
    </MenuContext.Provider>
  );
}

function MenuTrigger({
  asChild,
  ...props
}: Wide<MenuTriggerProps, React.ComponentProps<typeof MenuPrimitive.Trigger>>) {
  return <MenuPrimitive.Trigger data-slot="menu-trigger" asChild={asChild ?? false} {...props} />;
}

function MenuContent({
  className,
  align = "center",
  sideOffset = 4,
  onCloseAutoFocus,
  ...props
}: Wide<MenuContentProps, React.ComponentProps<typeof MenuPrimitive.Content>>) {
  const { skipReturnRef } = useContext(MenuContext);
  return (
    <MenuPrimitive.Portal>
      <MenuPrimitive.Content
        data-slot="menu-content"
        align={align}
        sideOffset={sideOffset}
        className={cn(
          MENU_CONTENT_CLASS,
          "z-50 max-h-(--radix-dropdown-menu-content-available-height) origin-(--radix-dropdown-menu-content-transform-origin) overflow-x-hidden overflow-y-auto rounded-md border bg-popover text-popover-foreground shadow-md data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95",
          className,
        )}
        {...props}
        onCloseAutoFocus={(event) => {
          onCloseAutoFocus?.(event);
          // Radix focuses the trigger unless the event is prevented. A `focusesElsewhere` row
          // has already focused its target by now, and the trigger would take it back.
          if (skipReturnRef.current) event.preventDefault();
          skipReturnRef.current = false;
        }}
      />
    </MenuPrimitive.Portal>
  );
}

function MenuItem({
  icon,
  label,
  trailing,
  destructive = false,
  disabled = false,
  onSelect,
  focusesElsewhere = false,
  className,
  href,
  link,
  ...props
}: Wide<MenuItemProps, Omit<React.ComponentProps<typeof MenuPrimitive.Item>, "children">>) {
  const { setOpen, skipReturnRef } = useContext(MenuContext);
  const row = (
    <>
      {icon}
      <span className={cn(MENU_ITEM_TEXT_CLASS, "truncate")}>{label}</span>
      {typeof trailing === "string" ? (
        <span className={cn(MENU_TRAILING_CLASS, "tracking-widest")}>{trailing}</span>
      ) : (
        trailing
      )}
    </>
  );
  // A link row is radix's item rendered *as* the anchor, not an anchor inside the item: the `<a>`
  // takes `role="menuitem"`, the roving focus and the keys, and the router's link keeps its own
  // hover and focus handlers. The nesting is not `<Link asChild>` because radix composes its
  // select after the item's own `onClick` and skips it once that has called `preventDefault` —
  // which every router's click does — so a menu handed the router's click would never close.
  // Cloned the other way, the router link is handed radix's click and runs it first. A disabled
  // row is no link at all, so nothing can follow it.
  const anchor = disabled ? undefined : link ? (
    cloneElement(link, undefined, row)
  ) : href !== undefined ? (
    <a href={href}>{row}</a>
  ) : undefined;
  return (
    <MenuPrimitive.Item
      data-slot="menu-item"
      data-variant={destructive ? "destructive" : "default"}
      disabled={disabled}
      textValue={label}
      {...props}
      asChild={anchor !== undefined}
      onSelect={(event) => {
        skipReturnRef.current = focusesElsewhere;
        if (focusesElsewhere) {
          // Radix runs this while the menu is still open and trapping focus, so an `autoFocus`
          // the action mounts is pulled straight back into the menu. Close it first — flushed,
          // so the trap is released — and only then hand focus away.
          event.preventDefault();
          flushSync(() => setOpen(false));
        }
        onSelect?.();
      }}
      // Icons inherit `currentColor` here, so the row's text colour is the icon's too — the web
      // half of what `IconClassContext` does on native.
      className={cn(
        MENU_ITEM_CLASS,
        MENU_ITEM_WEB_CLASS,
        destructive
          ? "text-destructive focus:bg-destructive/10 focus:text-destructive"
          : "text-popover-foreground focus:bg-accent focus:text-accent-foreground",
        className,
      )}
    >
      {anchor ?? row}
    </MenuPrimitive.Item>
  );
}

function MenuSeparator({
  className,
  ...props
}: Wide<MenuSeparatorProps, React.ComponentProps<typeof MenuPrimitive.Separator>>) {
  return (
    <MenuPrimitive.Separator
      data-slot="menu-separator"
      className={cn(MENU_SEPARATOR_CLASS, "pointer-events-none", className)}
      {...props}
    />
  );
}

/**
 * A toggle row's inside: `MenuItem`'s icon, label and trailing node, then the ✓ slot at the far
 * edge. `ItemIndicator` renders only while its row is on; the slot around it stays.
 */
function ToggleRowBody({
  icon,
  label,
  trailing,
}: Pick<MenuCheckboxItemProps, "icon" | "label" | "trailing">) {
  return (
    <>
      {icon}
      <span className={cn(MENU_ITEM_TEXT_CLASS, "truncate")}>{label}</span>
      {typeof trailing === "string" ? (
        <span className={cn(MENU_TRAILING_CLASS, "tracking-widest")}>{trailing}</span>
      ) : (
        trailing
      )}
      <span className={cn(MENU_INDICATOR_CLASS, "flex")}>
        <MenuPrimitive.ItemIndicator>
          <Check />
        </MenuPrimitive.ItemIndicator>
      </span>
    </>
  );
}

const TOGGLE_ROW_CLASS = cn(
  MENU_ITEM_CLASS,
  MENU_ITEM_WEB_CLASS,
  "text-popover-foreground focus:bg-accent focus:text-accent-foreground",
);

function MenuCheckboxItem({
  icon,
  label,
  trailing,
  checked,
  onCheckedChange,
  disabled = false,
  onSelect,
  className,
  ...props
}: Wide<
  MenuCheckboxItemProps,
  Omit<React.ComponentProps<typeof MenuPrimitive.CheckboxItem>, "children">
>) {
  return (
    <MenuPrimitive.CheckboxItem
      data-slot="menu-checkbox-item"
      disabled={disabled}
      textValue={label}
      {...props}
      checked={checked}
      onCheckedChange={(next) => onCheckedChange?.(next)}
      // Radix closes the menu on every select; a toggle list stays open between presses.
      onSelect={(event) => {
        onSelect?.(event);
        event.preventDefault();
      }}
      className={cn(TOGGLE_ROW_CLASS, className)}
    >
      <ToggleRowBody icon={icon} label={label} trailing={trailing} />
    </MenuPrimitive.CheckboxItem>
  );
}

function MenuRadioGroup({
  value,
  onValueChange,
  ...props
}: Wide<MenuRadioGroupProps, React.ComponentProps<typeof MenuPrimitive.RadioGroup>>) {
  return (
    <MenuPrimitive.RadioGroup
      data-slot="menu-radio-group"
      value={value}
      onValueChange={(next) => onValueChange?.(next)}
      {...props}
    />
  );
}

/** Choosing one closes the menu — radix's default, kept: a one-of-N choice is done once made. */
function MenuRadioItem({
  icon,
  label,
  trailing,
  disabled = false,
  className,
  ...props
}: Wide<
  MenuRadioItemProps,
  Omit<React.ComponentProps<typeof MenuPrimitive.RadioItem>, "children">
>) {
  return (
    <MenuPrimitive.RadioItem
      data-slot="menu-radio-item"
      disabled={disabled}
      textValue={label}
      {...props}
      className={cn(TOGGLE_ROW_CLASS, className)}
    >
      <ToggleRowBody icon={icon} label={label} trailing={trailing} />
    </MenuPrimitive.RadioItem>
  );
}

